-- Spectra clean development baseline V1.
--
-- Final baseline generated by applying the previous V1 through V34 migrations
-- in an isolated PostgreSQL database on 2026-08-25.
-- This migration owns the current schemas, tables, comments, constraints,
-- indexes, functions, triggers, runtime role boundary and ordinary seeds.
-- The spectra_core.sys_region table and its comments are retained, while the
-- large region row dataset is intentionally excluded and imported separately
-- from the JSON seed pack with scripts/import-regions.ps1.
-- No runtime users, departments, credentials, MFA records, assignments, or
-- security change outbox data are included in this clean baseline.

--
--



SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

--
-- Name: spectra_core; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA spectra_core;


--
-- Name: spectra_notification; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA spectra_notification;


--
-- Name: spectra_oa; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA spectra_oa;


--
-- Name: spectra_security; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA spectra_security;


--
-- Name: spectra_workflow; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA spectra_workflow;


--
-- Name: pgcrypto; Type: EXTENSION; Schema: -; Owner: -
--

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;


--
-- Name: EXTENSION pgcrypto; Type: COMMENT; Schema: -; Owner: -
--

COMMENT ON EXTENSION pgcrypto IS 'cryptographic functions';


--
-- Name: sec_reject_audit_mutation(); Type: FUNCTION; Schema: spectra_security; Owner: -
--

CREATE FUNCTION spectra_security.sec_reject_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'security_audit_event is append-only';
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

