-- Name: sys_service_monitor_alert_event; Type: TABLE; Schema: spectra_core; Owner: -
--

CREATE TABLE spectra_core.sys_service_monitor_alert_event (
    id uuid DEFAULT uuidv7() NOT NULL,
    rule_id uuid NOT NULL,
    rule_code character varying(80) NOT NULL,
    rule_name character varying(100) NOT NULL,
    metric_code character varying(80) NOT NULL,
    severity character varying(16) NOT NULL,
    state character varying(16) DEFAULT 'ACTIVE'::character varying NOT NULL,
    current_value character varying(120),
    threshold_value double precision,
    expected_value character varying(80),
    message character varying(500) NOT NULL,
    first_occurred_at timestamp(6) with time zone NOT NULL,
    last_occurred_at timestamp(6) with time zone NOT NULL,
    recovered_at timestamp(6) with time zone,
    occurrence_count integer DEFAULT 1 NOT NULL,
    last_notified_at timestamp(6) with time zone,
    created_by uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted timestamp(6) with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_sys_service_monitor_alert_event_occurrence CHECK ((occurrence_count >= 1)),
    CONSTRAINT ck_sys_service_monitor_alert_event_severity CHECK (((severity)::text = ANY ((ARRAY['WARNING'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT ck_sys_service_monitor_alert_event_state CHECK (((state)::text = ANY ((ARRAY['ACTIVE'::character varying, 'RECOVERED'::character varying])::text[])))
);


