--

CREATE TABLE spectra_core.sys_service_monitor_alert_rule (
    id uuid DEFAULT uuidv7() NOT NULL,
    code character varying(80) NOT NULL,
    name character varying(100) NOT NULL,
    metric_code character varying(80) NOT NULL,
    operator_code character varying(16) DEFAULT 'GTE'::character varying NOT NULL,
    threshold_value double precision,
    expected_value character varying(80),
    severity character varying(16) DEFAULT 'WARNING'::character varying NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    consecutive_failures integer DEFAULT 1 NOT NULL,
    cooldown_seconds integer DEFAULT 300 NOT NULL,
    remark character varying(500),
    created_by uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted timestamp(6) with time zone,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ck_sys_service_monitor_alert_rule_operator CHECK (((operator_code)::text = ANY ((ARRAY['GTE'::character varying, 'GT'::character varying, 'LTE'::character varying, 'LT'::character varying, 'EQ'::character varying, 'NE'::character varying])::text[]))),
    CONSTRAINT ck_sys_service_monitor_alert_rule_severity CHECK (((severity)::text = ANY ((ARRAY['WARNING'::character varying, 'CRITICAL'::character varying])::text[]))),
    CONSTRAINT ck_sys_service_monitor_alert_rule_values CHECK ((((consecutive_failures >= 1) AND (consecutive_failures <= 10)) AND ((cooldown_seconds >= 0) AND (cooldown_seconds <= 86400)) AND ((threshold_value IS NULL) OR (threshold_value >= (0)::double precision))))
);


