-- Name: sys_service_monitor_sample; Type: TABLE; Schema: spectra_core; Owner: -
--

CREATE TABLE spectra_core.sys_service_monitor_sample (
    id uuid DEFAULT uuidv7() NOT NULL,
    collected_at timestamp(6) with time zone NOT NULL,
    cpu_usage double precision DEFAULT 0 NOT NULL,
    cpu_logical_cores integer DEFAULT 0 NOT NULL,
    system_memory_usage double precision DEFAULT 0 NOT NULL,
    system_memory_total_bytes bigint DEFAULT 0 NOT NULL,
    system_memory_used_bytes bigint DEFAULT 0 NOT NULL,
    system_memory_available_bytes bigint DEFAULT 0 CONSTRAINT sys_service_monitor_sample_system_memory_available_byt_not_null NOT NULL,
    jvm_heap_usage double precision DEFAULT 0 NOT NULL,
    jvm_heap_used_bytes bigint DEFAULT 0 NOT NULL,
    jvm_heap_max_bytes bigint DEFAULT 0 NOT NULL,
    jvm_non_heap_used_bytes bigint DEFAULT 0 NOT NULL,
    live_thread_count integer DEFAULT 0 NOT NULL,
    peak_thread_count integer DEFAULT 0 NOT NULL,
    gc_count bigint DEFAULT 0 NOT NULL,
    qps double precision DEFAULT 0 NOT NULL,
    error_rate double precision DEFAULT 0 NOT NULL,
    p95_response_ms double precision DEFAULT 0 NOT NULL,
    request_metrics_available boolean DEFAULT false NOT NULL,
    status character varying(16) DEFAULT 'DOWN'::character varying NOT NULL,
    created_by uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted timestamp(6) with time zone,
    version bigint DEFAULT 0 NOT NULL,
    database_status character varying(16) DEFAULT 'UNKNOWN'::character varying NOT NULL,
    redis_status character varying(16) DEFAULT 'UNKNOWN'::character varying NOT NULL,
    CONSTRAINT ck_sys_service_monitor_sample_status CHECK (((status)::text = ANY ((ARRAY['HEALTHY'::character varying, 'WARNING'::character varying, 'DEGRADED'::character varying, 'DOWN'::character varying])::text[]))),
    CONSTRAINT ck_sys_service_monitor_sample_values CHECK (((cpu_usage >= (0)::double precision) AND (cpu_usage <= (100)::double precision) AND (system_memory_usage >= (0)::double precision) AND (system_memory_usage <= (100)::double precision) AND (jvm_heap_usage >= (0)::double precision) AND (jvm_heap_usage <= (100)::double precision) AND (cpu_logical_cores >= 0) AND (system_memory_total_bytes >= 0) AND (system_memory_used_bytes >= 0) AND (system_memory_available_bytes >= 0) AND (jvm_heap_used_bytes >= 0) AND (jvm_heap_max_bytes >= 0) AND (jvm_non_heap_used_bytes >= 0) AND (live_thread_count >= 0) AND (peak_thread_count >= 0) AND (gc_count >= 0) AND (qps >= (0)::double precision) AND (error_rate >= (0)::double precision) AND (p95_response_ms >= (0)::double precision)))
);


