--

CREATE TABLE spectra_core.sys_system_state (
    id uuid DEFAULT uuidv7() CONSTRAINT __canonical_sys_system_state_id_not_null NOT NULL,
    state_key character varying(32) CONSTRAINT __canonical_sys_system_state_state_key_not_null NOT NULL,
    state character varying(32) DEFAULT 'UNINITIALIZED'::character varying CONSTRAINT __canonical_sys_system_state_state_not_null NOT NULL,
    initialization_id uuid,
    initialized_at timestamp(6) with time zone,
    initialized_by uuid,
    created_by uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT __canonical_sys_system_state_created_at_not_null NOT NULL,
    updated_by uuid,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP CONSTRAINT __canonical_sys_system_state_updated_at_not_null NOT NULL,
    deleted timestamp(6) with time zone,
    version bigint DEFAULT 0 CONSTRAINT __canonical_sys_system_state_version_not_null NOT NULL,
    CONSTRAINT ck_sys_system_state_key CHECK (((state_key)::text = ANY ((ARRAY['SYSTEM'::character varying, 'SYSTEM_GUIDE'::character varying])::text[]))),
    CONSTRAINT ck_sys_system_state_value CHECK (((((state_key)::text = 'SYSTEM'::text) AND ((state)::text = ANY ((ARRAY['UNINITIALIZED'::character varying, 'INITIALIZING'::character varying, 'INITIALIZED'::character varying])::text[]))) OR (((state_key)::text = 'SYSTEM_GUIDE'::text) AND ((state)::text = ANY ((ARRAY['PENDING'::character varying, 'COMPLETED'::character varying])::text[])))))
);


