--

CREATE TABLE spectra_core.sys_user_import_task (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    operator_id uuid NOT NULL,
    idempotency_key character varying(120) NOT NULL,
    file_name character varying(255) NOT NULL,
    file_hash character varying(128) NOT NULL,
    skip_existing boolean DEFAULT false NOT NULL,
    status character varying(20) NOT NULL,
    request_hash character varying(64) NOT NULL,
    profile_version_hash character varying(64) NOT NULL,
    preview_token_hash character varying(64),
    preview_expires_at timestamp(6) with time zone,
    expires_at timestamp(6) with time zone NOT NULL,
    total_rows integer DEFAULT 0 NOT NULL,
    valid_rows integer DEFAULT 0 NOT NULL,
    error_rows integer DEFAULT 0 NOT NULL,
    skipped_rows integer DEFAULT 0 NOT NULL,
    applied_rows integer DEFAULT 0 NOT NULL,
    assignment_count integer DEFAULT 0 NOT NULL,
    access_boundary_count integer DEFAULT 0 NOT NULL,
    grant_boundary_count integer DEFAULT 0 NOT NULL,
    preview_consumed_at timestamp(6) with time zone,
    created_by uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted timestamp(6) with time zone,
    version bigint DEFAULT 0 NOT NULL,
    completed_rows integer DEFAULT 0 NOT NULL,
    CONSTRAINT ck_sys_user_import_task_completed_rows CHECK ((completed_rows >= 0)),
    CONSTRAINT ck_sys_user_import_task_counts CHECK (((total_rows >= 0) AND (valid_rows >= 0) AND (error_rows >= 0) AND (skipped_rows >= 0) AND (applied_rows >= 0) AND (assignment_count >= 0) AND (access_boundary_count >= 0) AND (grant_boundary_count >= 0))),
    CONSTRAINT ck_sys_user_import_task_status CHECK (((status)::text = ANY ((ARRAY['UPLOADED'::character varying, 'VALIDATING'::character varying, 'PREVIEWED'::character varying, 'APPLYING'::character varying, 'SUCCEEDED'::character varying, 'PARTIAL_FAILED'::character varying, 'FAILED'::character varying, 'EXPIRED'::character varying])::text[])))
);


